if (ctx.rigsignal?.fps?.current != null && ctx.rigsignal.fps.current < 0) {
  throw new Exception('rigsignal.fps.current must be >= 0, got: ' + ctx.rigsignal.fps.current);
}
if (ctx.rigsignal?.fps?.frametime_ms != null && ctx.rigsignal.fps.frametime_ms < 0) {
  throw new Exception('rigsignal.fps.frametime_ms must be >= 0');
}

if (ctx.rigsignal == null) ctx.rigsignal = [:];
if (ctx.rigsignal.fps == null) ctx.rigsignal.fps = [:];
def variance = ctx.rigsignal?.fps?.frametime_variance;
ctx.rigsignal.fps.stutter_detected = (variance != null && variance > 8.0);
